    # Annotate a *copy* of each artifact with a mutable Reasons list. We never
    # mutate the caller's input objects.
    $items = foreach ($a in $Artifacts) {
        [PSCustomObject]@{
            Name          = $a.Name
            SizeBytes     = [long]$a.SizeBytes
