        ([regex]::Match($block, 'SPACE_RECLAIMED_HUMAN=([^\r\n]+)')).Groups[1].Value.Trim() | Should -Be $ReclaimedHuman
        ([regex]::Match($block, 'DRY_RUN=(\w+)')).Groups[1].Value              | Should -Be $DryRun
    }
}

